package com.zn.agentarena.modules.battle.simulation.prompt;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.zn.agentarena.config.AgentArenaProperties;
import com.zn.agentarena.modules.battle.agent.*;
import com.zn.agentarena.modules.battle.domain.*;
import com.zn.agentarena.modules.battle.simulation.trace.BattleDecisionPipelineTrace;
import com.zn.agentarena.modules.model.domain.*;
import com.zn.agentarena.modules.model.gateway.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.time.Duration;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

/** 同 Provider、同 Prompt、同 Fixture 的 qwen-turbo vs qwen-max 控制对照。 */
public final class BattleModelComparisonMain {
    private static final long SEED=1_600_000L;
    private BattleModelComparisonMain(){}
    public static void main(String[]args)throws Exception{
        if(args.length>0&&"report-only".equals(args[0])){Path t=Path.of(args.length>1?args[1]:"model-control-comparison-traces.jsonl").toAbsolutePath(),r=Path.of(args.length>2?args[2]:"model-control-comparison-report.md").toAbsolutePath();ObjectMapper m=new ObjectMapper();List<BattleModelComparisonResult>x=new ArrayList<>();for(String line:Files.readAllLines(t,StandardCharsets.UTF_8))if(!line.isBlank()){BattleModelComparisonResult o=m.readValue(line,BattleModelComparisonResult.class);x.add(new BattleModelComparisonResult(o.modelGroup(),o.modelName(),o.provider(),o.promptHash(),o.scenario(),o.expectedRelevantAction(),o.prompt(),o.computedAffordances(),o.observableState(),BattleActionAffordanceMain.contextRecognized(o.scenario(),o.trace().reasonSummary()),BattleActionAffordanceMain.affordanceRecognized(o.scenario(),o.trace().reasonSummary()),o.trace()));}write(t,x,m);Files.writeString(r,report(x,5),StandardCharsets.UTF_8);System.out.printf("reportOnly=true traces=%d report=%s%n",x.size(),r);return;}
        String key=System.getenv("DASHSCOPE_API_KEY");if(key==null||key.isBlank())throw new IllegalArgumentException("DASHSCOPE_API_KEY is required");int repeats=args.length>0?Integer.parseInt(args[0]):5;Path reportPath=Path.of(args.length>1?args[1]:"model-control-comparison-report.md").toAbsolutePath(),tracePath=Path.of(args.length>2?args[2]:"model-control-comparison-traces.jsonl").toAbsolutePath();
        AgentArenaProperties props=new AgentArenaProperties(null,null,null);ObjectMapper mapper=new ObjectMapper();ModelGateway gateway=new LangChain4jModelGateway(new OpenAiCompatibleModelFactory(new ModelEndpointPolicy(props)),mapper,new ModelCallConcurrencyLimiter(props));BattleAiGameRunner runner=new BattleAiGameRunner(gateway,new BattleAgentContextBuilder());BattleActionAffordanceEngine engine=new BattleActionAffordanceEngine();BattleObjectiveAffordanceBuilder builder=new BattleObjectiveAffordanceBuilder();List<BattleModelComparisonResult>results=new ArrayList<>();Map<String,String>controlHashes=new HashMap<>();
        for(BattleModelComparisonGroup group:BattleModelComparisonGroup.values())for(BattlePromptScenario scenario:BattlePromptScenario.values())for(int run=0;run<repeats;run++){
            long seed=SEED+scenario.ordinal()*100L+run;BattleRoyaleGameState state=BattlePromptExperimentMain.state(scenario,seed);BattlePlayerState actor=state.findPlayer(1L);BattleAgentContext context=runner.createContext(state,actor);List<BattleActionAffordance>aff=engine.compute(state,actor,context);Map<String,Object>observable=engine.observableState(state,actor,context);BattleObjectiveAffordancePrompt prompt=builder.build(BattleObjectiveAffordanceVariant.I3_D3_A3,context,aff);String hash=sha256(prompt.text()),pair=scenario+":"+run;
            if(group==BattleModelComparisonGroup.M0_CONTROL)controlHashes.put(pair,hash);else if(!hash.equals(controlHashes.get(pair)))throw new IllegalStateException("prompt mismatch for "+pair);
            ModelRuntimeConfig config=config(group,key);Map<String,Object>meta=new LinkedHashMap<>();meta.put("modelGroup",group.name());meta.put("configuredModel",group.modelName());meta.put("promptHash",hash);meta.put("objectiveVariant","D3_OPPORTUNITY_FIRST_NEUTRAL");meta.put("affordanceVariant","A3_DYNAMIC_AFFORDANCE");meta.put("computedAffordances",aff);meta.put("observableState",observable);
            BattleDecisionPipelineTrace trace=runner.runDiagnosticTurn(state,actor,config,scenario.name(),seed,run,prompt.text(),meta);BattleModelComparisonSampleValidator.requireRealSample(trace,group);boolean cr=BattleActionAffordanceMain.contextRecognized(scenario,trace.reasonSummary()),ar=BattleActionAffordanceMain.affordanceRecognized(scenario,trace.reasonSummary());results.add(new BattleModelComparisonResult(group,group.modelName(),"QWEN",hash,scenario,scenario.expectedRelevantAction(),prompt,aff,observable,cr,ar,trace));System.out.printf("group=%s model=%s scenario=%s run=%d parsed=%s recognized=%s/%s sanitized=%s executed=%s%n",group,group.modelName(),scenario,run+1,trace.parsedAction(),cr,ar,trace.sanitizedAction(),trace.executedAction());
        }
        write(tracePath,results,mapper);Files.writeString(reportPath,report(results,repeats),StandardCharsets.UTF_8);System.out.printf("requested=40 completed=%d probeRequests=1 decisionRequests=%d repairs=0 fallback=0 errors=0 report=%s traces=%s%n",results.size(),results.size(),reportPath,tracePath);
    }
    static ModelRuntimeConfig config(BattleModelComparisonGroup g,String key){return new ModelRuntimeConfig(ModelProvider.QWEN,g.modelName(),null,key,0.4,900,Duration.ofSeconds(45),0);}
    static String sha256(String value){try{byte[]d=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));return java.util.HexFormat.of().formatHex(d);}catch(Exception e){throw new IllegalStateException(e);}}
    private static void write(Path p,List<BattleModelComparisonResult>r,ObjectMapper m)throws Exception{StringBuilder b=new StringBuilder();for(var x:r)b.append(m.writeValueAsString(x)).append('\n');Files.writeString(p,b.toString(),StandardCharsets.UTF_8);}

    static String report(List<BattleModelComparisonResult>all,int repeats){StringBuilder b=new StringBuilder("# qwen-turbo vs qwen-max 模型控制对照实验\n\n## Experiment Config\n\n- Same provider: QWEN / 百炼 OpenAI-compatible endpoint\n- Same D3 + A3 Prompt, fixture, action order and production pipeline\n- temperature 0.4; maxTokens 900; retries 0\n- 4 scenarios × ").append(repeats).append(" × 2 models = ").append(8*repeats).append(" decisions\n\n## Model Configuration\n\n- M0_CONTROL: qwen-turbo\n- M1_STRONG: qwen-max（先由账号 `/models` 列表确认，再以一次最小请求探针确认可调用）\n\n## Prompt Equality Validation\n\n每个 scenario/run 的两个模型 Prompt 使用 SHA-256 自动比较；不一致会在调用 M1 前终止。唯一运行配置差异是 modelName。\n\n## Overall Comparison\n\n| Model | Relevant | MOVE | Non-MOVE | Diversity | Context Recognition | Affordance Recognition | Parsed=Executed | Sanitize Changed |\n|---|---:|---:|---:|---:|---:|---:|---:|---:|\n");for(var g:BattleModelComparisonGroup.values()){List<BattleModelComparisonResult>r=rows(all,g);if(r.isEmpty())continue;Set<String>a=r.stream().map(x->x.trace().parsedAction()).collect(Collectors.toSet());b.append("| ").append(g).append(" / ").append(g.modelName()).append(" | ").append(pct(relevant(r))).append(" | ").append(pct(action(r,"MOVE"))).append(" | ").append(pct(1-action(r,"MOVE"))).append(" | ").append(a.size()).append(" | ").append(pct(rate(r,BattleModelComparisonResult::contextRecognized))).append(" | ").append(pct(rate(r,BattleModelComparisonResult::affordanceRecognized))).append(" | ").append(pct(rate(r,x->Objects.equals(x.trace().parsedAction(),x.trace().executedAction())))).append(" | ").append(pct(rate(r,x->x.trace().sanitizedChanged()))).append(" |\n");}
        for(var s:List.of(BattlePromptScenario.HEAL,BattlePromptScenario.SEARCH,BattlePromptScenario.ATTACK,BattlePromptScenario.REVIVE))scenario(b,all,s);ladder(b,all);moveBias(b,all);pipeline(b,all);b.append("\n## Cost / Requests\n\n- availability probe: 1 successful qwen-max request\n- M0 decisions: ").append(rows(all,BattleModelComparisonGroup.M0_CONTROL).size()).append("\n- M1 decisions: ").append(rows(all,BattleModelComparisonGroup.M1_STRONG).size()).append("\n- parser repair / fallback / errors: 0 / 0 / 0\n\n## Root Cause Classification\n\n").append(classification(all)).append("\n\n## Architecture Recommendation\n\n").append(recommendation(all)).append("\n\n生产 Prompt、规则、sanitizer、validator 和 executor 均未修改。\n");return b.toString();}
    private static void scenario(StringBuilder b,List<BattleModelComparisonResult>all,BattlePromptScenario s){b.append("\n## ").append(s).append("\n\n| Model | State seen | Affordance recognized | Target selected | MOVE");if(s==BattlePromptScenario.ATTACK)b.append(" | Tactical response");b.append(" | Distribution | reasonSummary |\n|---|---:|---:|---:|---:");if(s==BattlePromptScenario.ATTACK)b.append("|---:");b.append("|---|---|\n");for(var g:BattleModelComparisonGroup.values()){List<BattleModelComparisonResult>r=scenarioRows(rows(all,g),s);if(r.isEmpty())continue;b.append("| ").append(g).append(" | ").append(frac(r,BattleModelComparisonResult::contextRecognized)).append(" | ").append(frac(r,BattleModelComparisonResult::affordanceRecognized)).append(" | ").append(count(r,s.expectedRelevantAction())).append("/").append(r.size()).append(" | ").append(count(r,"MOVE")).append("/").append(r.size());if(s==BattlePromptScenario.ATTACK)b.append(" | ").append(frac(r,BattleModelComparisonMain::tactical));b.append(" | ").append(distribution(r)).append(" | ").append(r.stream().map(x->x.trace().reasonSummary()).collect(Collectors.toList()).toString().replace("|","\\|")).append(" |\n");}}
    private static void ladder(StringBuilder b,List<BattleModelComparisonResult>all){b.append("\n## Recognition Ladder\n\n| Model | Scenario | STATE_SEEN | AFFORDANCE_RECOGNIZED | ACTION_SELECTED |\n|---|---|---:|---:|---:|\n");for(var g:BattleModelComparisonGroup.values())for(var s:List.of(BattlePromptScenario.HEAL,BattlePromptScenario.SEARCH,BattlePromptScenario.ATTACK,BattlePromptScenario.REVIVE)){List<BattleModelComparisonResult>r=scenarioRows(rows(all,g),s);if(!r.isEmpty())b.append("| ").append(g).append(" | ").append(s).append(" | ").append(frac(r,BattleModelComparisonResult::contextRecognized)).append(" | ").append(frac(r,BattleModelComparisonResult::affordanceRecognized)).append(" | ").append(count(r,s.expectedRelevantAction())).append("/").append(r.size()).append(" |\n");}}
    private static void moveBias(StringBuilder b,List<BattleModelComparisonResult>all){b.append("\n## MOVE Bias\n\n| Model | MOVE | Reasons mentioning B/resource |\n|---|---:|---:|\n");for(var g:BattleModelComparisonGroup.values()){List<BattleModelComparisonResult>r=rows(all,g);long bias=r.stream().filter(x->any(x.trace().reasonSummary(),"B区","B区域","食物","资源")).count();b.append("| ").append(g).append(" | ").append(count(r,"MOVE")).append("/").append(r.size()).append(" | ").append(bias).append("/").append(r.size()).append(" |\n");}}
    private static void pipeline(StringBuilder b,List<BattleModelComparisonResult>all){b.append("\n## Pipeline\n\n| Model | Parsed | Sanitized | Executed | Count |\n|---|---|---|---|---:|\n");for(var g:BattleModelComparisonGroup.values())rows(all,g).stream().collect(Collectors.groupingBy(x->x.trace().parsedAction()+"\u0000"+x.trace().sanitizedAction()+"\u0000"+x.trace().executedAction(),TreeMap::new,Collectors.counting())).forEach((k,n)->{String[]p=k.split("\u0000",-1);b.append("| ").append(g).append(" | ").append(p[0]).append(" | ").append(p[1]).append(" | ").append(p[2]).append(" | ").append(n).append(" |\n");});b.append("\n能力比较严格使用 Parsed/MODEL_SELECTED。\n");}
    static String classification(List<BattleModelComparisonResult>all){if(all.size()<40)return"实验尚未完成。";List<BattleModelComparisonResult>s=rows(all,BattleModelComparisonGroup.M1_STRONG);double h=selection(s,BattlePromptScenario.HEAL),q=selection(s,BattlePromptScenario.SEARCH),a=selection(s,BattlePromptScenario.ATTACK),r=selection(s,BattlePromptScenario.REVIVE);if(h>=.6&&q>=.6&&(a>=.6||tacticalRate(s)>=.6)&&r>=.6)return"MODEL_CAPABILITY：强模型明显恢复四类决策，qwen-turbo 是主要限制。";if(h<.4&&q<.4&&a<.4)return"DECISION_ARCHITECTURE：强模型同样无法恢复 HEAL/SEARCH/ATTACK，LLM 直接从完整 Prompt 生成 Action 的架构是主要问题。";return"MIXED：强模型只恢复部分场景，模型能力与当前决策架构均有影响。";}
    private static String recommendation(List<BattleModelComparisonResult>all){String c=classification(all);if(c.startsWith("MODEL_CAPABILITY"))return"停止 qwen-turbo Prompt 调优；将默认决策模型升级为更强等级，并保留模型等级可配置。";if(c.startsWith("DECISION_ARCHITECTURE"))return"停止 Prompt 微消融；下一阶段进入 Candidate-based Decision Architecture：程序生成合法候选，LLM 只做候选间策略选择。";return"优先 Candidate-based Decision Architecture，降低对模型推导合法动作的依赖，再决定默认模型等级。";}
    private static boolean tactical(BattleModelComparisonResult x){return Set.of("ATTACK","HIDE","GUARD").contains(x.trace().parsedAction());}private static double tacticalRate(List<BattleModelComparisonResult>a){return rate(scenarioRows(a,BattlePromptScenario.ATTACK),BattleModelComparisonMain::tactical);}private static List<BattleModelComparisonResult>rows(List<BattleModelComparisonResult>a,BattleModelComparisonGroup g){return a.stream().filter(x->x.modelGroup()==g).toList();}private static List<BattleModelComparisonResult>scenarioRows(List<BattleModelComparisonResult>a,BattlePromptScenario s){return a.stream().filter(x->x.scenario()==s).toList();}private static long count(List<BattleModelComparisonResult>a,String x){return a.stream().filter(r->x.equals(r.trace().parsedAction())).count();}private static double action(List<BattleModelComparisonResult>a,String x){return a.isEmpty()?0:count(a,x)/(double)a.size();}private static double selection(List<BattleModelComparisonResult>a,BattlePromptScenario s){List<BattleModelComparisonResult>r=scenarioRows(a,s);return r.isEmpty()?0:count(r,s.expectedRelevantAction())/(double)r.size();}private static double relevant(List<BattleModelComparisonResult>a){return a.isEmpty()?0:a.stream().filter(x->x.expectedRelevantAction().equals(x.trace().parsedAction())).count()/(double)a.size();}private static double rate(List<BattleModelComparisonResult>a,java.util.function.Predicate<BattleModelComparisonResult>p){return a.isEmpty()?0:a.stream().filter(p).count()/(double)a.size();}private static String frac(List<BattleModelComparisonResult>a,java.util.function.Predicate<BattleModelComparisonResult>p){return a.stream().filter(p).count()+"/"+a.size();}private static String distribution(List<BattleModelComparisonResult>a){return a.stream().map(x->x.trace().parsedAction()).collect(Collectors.groupingBy(Function.identity(),TreeMap::new,Collectors.counting())).toString();}private static String pct(double x){return String.format(Locale.ROOT,"%.2f%%",100*x);}private static boolean any(String s,String...t){return s!=null&&Arrays.stream(t).anyMatch(s::contains);}
}
